#!/usr/bin/env python3
import http.server
import json
import os
import posixpath

STORAGE_DIR = "__tmp_store__"

class PyPIHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        # Normalize empty paths
        if not self.path.startswith('/simple/') and self.path.lstrip('/') == '':
            self.path = '/simple/'

        # Simple directory listing
        if self.path == '/simple/':
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.end_headers()
            html = '<html><head><title>Simple River</title></head><body><h1>Simple River Index</h1><ul>'
            base = os.path.join(STORAGE_DIR, 'pypi')
            for f in sorted(os.listdir(base)):
                if f.endswith(('.tar.gz', '.whl')):
                    html += f'<li><a href="/simple/{f}">{f}</a></li>'
            html += '</ul></body></html>'
            self.wfile.write(html.encode())
            return

        self.send_response(404)
        self.end_headers()
        self.wfile.write(b'Not Found')

    def do_POST(self):
        if self.path.startswith('/simple/'):
            self.send_response(200)
            self.end_headers()
        else:
            self.send_response(200)
            self.end_headers()

    def do_HEAD(self):
        if self.path.startswith('/simple/'):
            self.send_response(200)
            self.end_headers()
        else:
            self.send_response(200)
            self.end_headers()

    def do_DELETE(self):
        if self.path.startswith('/simple/'):
            self.send_response(200)
            self.end_headers()
        else:
            self.send_response(200)
            self.end_headers()

if __name__ == '__main__':
    os.makedirs(STORAGE_DIR, exist_ok=True)
    server = http.server.HTTPServer(('127.0.0.1', 8080), PyPIHandler)
    print("PyPI server at http://127.0.0.1:8080")
    server.serve_forever()
